code_before:
/* CSS */
.error-badge { background-image: url("error-icon.png"); }

<!-- HTML (no text alternative for the error state) -->
<span class="error-badge"></span>

code_after:
/* Option 1: Inline image with alt text */
<span class="error-badge">
  <img src="error-icon.png" alt="Error">
</span>

/* Option 2: Visually-hidden text */
<span class="error-badge">
  <span class="visually-hidden">Error: </span>
</span>

/* CSS for visually-hidden helper */
.visually-hidden {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}
